with enriched as (select id, customer_id, plan, start_date, end_date, monthly_fee, status, cume_dist() over (order by monthly_fee desc) as monthly_fee_cume_dist, row_number() over w_ordered as seq_no from subscriptions window w_ordered as (partition by plan order by start_date desc, id)), with_windows as (select id, customer_id, plan, start_date, end_date, monthly_fee, status, monthly_fee_cume_dist, seq_no, lead(monthly_fee_cume_dist, 1, 0) over (order by start_date, id) as next_monthly_fee_cume_dist, first_value(seq_no) ignore nulls over (order by end_date, id rows between unbounded preceding and current row) as first_known_seq_no, row_number() over w_grp as event_seq from enriched window w_grp as (partition by plan order by end_date, id)), valid as (select id, customer_id, plan, start_date, status, seq_no, next_monthly_fee_cume_dist, event_seq, datediff(end_date, start_date) as days_start_date_to_end_date from with_windows where end_date > date '2023-10-07') select *, avg(next_monthly_fee_cume_dist) over (partition by customer_id order by days_start_date_to_end_date, id rows between 2 preceding and current row) as next_monthly_fee_cume_dist_avg_2, sum(next_monthly_fee_cume_dist) over w_part as running_next_monthly_fee_cume_dist, round(event_seq / sum(event_seq) over (partition by status), 4) as event_seq_share, first_value(next_monthly_fee_cume_dist, true) over (partition by plan order by days_start_date_to_end_date, id rows between unbounded preceding and current row) as first_known_next_monthly_fee_cume_dist from valid window w_part as (partition by plan, status order by seq_no, id rows between unbounded preceding and current row);
